"""Build authored fact records, never infer free slots from missing walkthrough rows."""
import json,datetime,pathlib
P=pathlib.Path(__file__).parent
BASE=datetime.date(2009,4,1)
def date(mmdd):
 m,d=map(int,mmdd.split('-'));real=datetime.date(2010 if m<4 else 2009,m,d)
 return {'mmdd':mmdd,'ordinal':(real-BASE).days,'weekday':real.isoweekday()}
def write(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
