for n,start,end,low,cap in spec:
 stages.append({'id':'p3r.tower.stage_'+n,'labelZh':'塔尔塔罗斯 '+str(low)+'—'+str(cap)+'F','floorStart':low,'floorCeiling':cap,'startInclusive':date(start) if start else None,'endExclusive':date(end) if end else None,'verificationStatus':'contested' if n in ['02','03','08','09'] else 'corroborated','planningEnabled':n=='10','countUnit':'optional_exploration_night' if n!='11' else 'mandatory_story_operation','sources':['wiki_tower','pst_tower'],'unknownFields':['earliest_available_nights','party_absences'] if n!='10' else [],'dateConflicts':(['06-13','06-14'] if n in ['02','03'] else ['12-03','12-10'] if n in ['08','09'] else []),'note':'Only stage10 currently mapped to playable slice. Stage11 mandatory final operation excluded from optional-visit cap; floor264 cap needs separate final-stage validation.' if n=='11' else 'Floor ceilings do not guarantee combat completion.'})
